OUT = ROOT / "gateway" / "internal" / "airframe" / "testdata" / "state.json"
SERVER = "https://k.invalid"
_re_ns = _re0.compile(r"^(app|infra)-([a-z0-9]+)-")
PLURAL = {k: v["plural"] for k, v in CONTRACT["xrds"].items()}
REG = airframe_plan.Registry("kind-dev", ("kind-prod",), "gitops-cluster-dev-tenants")


def path_of(obj: dict) -> str:
    md = obj["metadata"]
    if obj["kind"] == "Application":
        return argo_path("applications", md["namespace"], md["name"])
    if obj["kind"] == "Rollout":
        return argo_path("rollouts", md["namespace"], md["name"])
    return xr_path(PLURAL[obj["kind"]], md["namespace"], md["name"])


class World:
    """A fake API server over a set of objects: a GET of an object path answers the object or 404, a GET of a list path the
    objects below it that match labelSelector, a page at a time when `pages` says so. `status` overrides the answer of a path."""

    def __init__(self, objects=(), status=None, pages=None, raw=None):
        self.objects = {path_of(o): o for o in objects}
        # the platform's Namespaces, each labelled with its app (Python never reads them; Go does before it reads in a namespace)
        for ns in sorted({o["metadata"]["namespace"] for o in objects if o["metadata"].get("namespace")}):
            m = _re_ns.match(ns)
            if m:
                # the lab's real shapes: an environment namespace carries hangar.io/app, a -cicd namespace carries none
                md = {"name": ns} if ns.endswith("-cicd") else {"name": ns, "labels": {"hangar.io/app": m.group(2)}}
                self.objects["/api/v1/namespaces/" + ns] = {"kind": "Namespace", "metadata": md}
        self.status, self.pages, self.raw = status or {}, pages or {}, raw or {}
        self.seen: list[dict] = []
        self.lock = threading.Lock()

    def opener(self, req, timeout, ctx):
        u = urllib.parse.urlsplit(req.full_url)
        q = dict(urllib.parse.parse_qsl(u.query, keep_blank_values=True))
        target = u.path + (("?" + u.query) if u.query else "")
        path = u.path
        status, body = 200, None
        if path in self.status:
            status, body = self.status[path], {"kind": "Status", "message": "from the fixture"}
        elif path in self.raw:
            body = self.raw[path]
        elif path in self.objects:
            body = self.objects[path]
        else:
            parent_items = sorted(((p, o) for p, o in self.objects.items() if p.rsplit("/", 1)[0] == path))
            seg = path.rsplit("/", 1)[-1]
            is_list = path.count("/") == 6 and (seg in PLURAL.values() or seg in ("applications", "rollouts"))
            if is_list:
                sel = dict(kv.split("=", 1) for kv in q["labelSelector"].split(",")) if q.get("labelSelector") else {}
                items = [o for _, o in parent_items
                         if all((o["metadata"].get("labels") or {}).get(k) == v for k, v in sel.items())]
                body = {"items": items}
                n = self.pages.get(path)
                if n:
                    off = int(q.get("continue") or 0)
                    body = {"items": items[off:off + n]}
                    if off + n < len(items):
                        body["metadata"] = {"continue": str(off + n)}
            else:
                status, body = 404, {"kind": "Status", "reason": "NotFound"}
        raw = body if isinstance(body, bytes) else json.dumps(body).encode()
        with self.lock:
            self.seen.append({"target": target, "status": status, "body": json.loads(raw) if raw else None})
        return status, raw


def xr(kind, ns, name, gen=1, conds=(), spec=None, status=None, labels=None):
    md = {"name": name, "namespace": ns, "generation": gen}
    if labels:
        md["labels"] = labels
    st = dict(status or {})
    if conds is not None:
        st["conditions"] = [dict(c) for c in conds]
    return {"apiVersion": "catalog.hangar.io/v1alpha1", "kind": kind, "metadata": md, "spec": spec or {}, "status": st}


def c(type_, status="True", reason=None, message=None, obs=None):
    out = {"type": type_, "status": status}
    if reason is not None:
        out["reason"] = reason
    if message is not None:
        out["message"] = message
    if obs is not None:
        out["observedGeneration"] = obs
    return out


def app_obj(name, ns, app, env, resources=(), labels=None, spec=None, status=None):
    lab = {"hangar.io/app": app, "hangar.io/env": env, **(labels or {})}
    return {"apiVersion": "argoproj.io/v1alpha1", "kind": "Application", "metadata": {"name": name, "namespace": ns, "labels": lab},
            "spec": spec or {"project": f"{app}-lower", "destination": {"server": "https://kubernetes.default.svc", "namespace": f"app-{app}-{env}"},
                             "sources": [{"repoURL": f"https://github.com/o/gitops-{app}", "path": f"{env}", "targetRevision": "main"},
                                         {"repoURL": f"https://github.com/o/{app}", "targetRevision": "HEAD"}]},
            "status": status or {"sync": {"status": "Synced", "revisions": ["a" * 40, "b" * 40]},
                                 "health": {"status": "Healthy", "message": "ok"},
                                 "operationState": {"phase": "Succeeded", "message": "done", "finishedAt": "2026-11-14T10:00:00Z"},
                                 "reconciledAt": "2026-11-14T10:01:00Z", "resources": list(resources)}}


def rollout(name, ns, gen=3, obs="3", phase="Healthy", strategy=None, images=("ghcr.io/o/shop:1",)):
    return {"apiVersion": "argoproj.io/v1alpha1", "kind": "Rollout", "metadata": {"name": name, "namespace": ns, "generation": gen},
            "spec": {"replicas": 2, "strategy": strategy or {"canary": {"steps": []}},
                     "template": {"spec": {"containers": [{"name": "app", "image": i} for i in images]}}},
            "status": {"phase": phase, "message": "m" * 400 if phase == "Degraded" else "", "readyReplicas": 2, "availableReplicas": 2,
                       "updatedReplicas": 2, "currentStepIndex": 1, "stableRS": "abc", "currentPodHash": "def", "observedGeneration": obs}}


